import csv
import io
import re


_EXPECTED_COLUMNS = [
    "DATE",
    "TIME",
    "Qty",
    "PRODUCTID",
    "Price",
    "ProductType",
    "ProductDescription",
    "URL",
    "Comments",
]


def _normalize_header(value):
    return re.sub(r"[^a-z0-9]+", "", value.lstrip("\ufeff").lower())


def _header_score(row):
    if not row:
        return 0
    expected = [_normalize_header(value) for value in _EXPECTED_COLUMNS]
    normalized = [_normalize_header(value) for value in row]
    score = 0
    for index, value in enumerate(normalized):
        if index < len(expected) and value == expected[index]:
            score += 3
        elif value in expected:
            score += 1
    return score


def _fallback_parse(text):
    rows = []
    row = []
    field = []
    in_quotes = False
    field_started = False
    index = 0
    length = len(text)

    while index < length:
        char = text[index]

        if in_quotes:
            if char == '"':
                if index + 1 < length and text[index + 1] == '"':
                    field.append('"')
                    index += 2
                    continue
                in_quotes = False
            else:
                field.append(char)
            index += 1
            continue

        if char == '"' and not field_started:
            in_quotes = True
            field_started = True
            index += 1
            continue

        if char == ",":
            row.append("".join(field))
            field = []
            field_started = False
            index += 1
            continue

        if char == "\r" or char == "\n":
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            field_started = False
            if char == "\r" and index + 1 < length and text[index + 1] == "\n":
                index += 2
            else:
                index += 1
            continue

        field.append(char)
        field_started = True
        index += 1

    if field_started or field or row:
        row.append("".join(field))
        rows.append(row)

    return rows


def _parse_records(text):
    try:
        csv.field_size_limit(100000000)
    except (OverflowError, ValueError):
        pass

    try:
        reader = csv.reader(
            io.StringIO(text, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
        return [list(row) for row in reader]
    except (csv.Error, UnicodeError):
        return _fallback_parse(text)


def _find_header_start(raw_csv):
    offset = 0
    best_offset = None
    best_score = 0

    for line in raw_csv.splitlines(True):
        records = _parse_records(line)
        if len(records) == 1:
            score = _header_score(records[0])
            if score > best_score:
                best_score = score
                best_offset = offset
            if score >= 24:
                return offset
        offset += len(line)

    if best_score >= 12:
        return best_offset
    return None


def _looks_like_url(value):
    return bool(re.match(r"^\s*(?:(?:https?|ftp)://|www\.)", value, re.IGNORECASE))


def _split_middle(values):
    if not values:
        return "", ""
    if len(values) == 1:
        return values[0], ""
    if len(values) == 2:
        return values[0], values[1]

    description_start = None
    for index in range(1, len(values)):
        text = values[index].strip()
        if len(text) >= 35 or re.search(r"[.!?]\s*$", text):
            description_start = index
            break

    if description_start is None:
        description_start = 1

    product_type = ",".join(values[:description_start])
    description = ",".join(values[description_start:])
    return product_type, description


def _repair_row(row, width):
    values = [str(value) for value in row]

    if len(values) == width:
        return values

    if not values:
        return [""] * width

    url_indices = [
        index for index, value in enumerate(values)
        if _looks_like_url(value)
    ]

    if url_indices:
        url_index = min(url_indices, key=lambda index: abs(index - 7))
        if url_index >= 5:
            prefix = values[:5]
            while len(prefix) < 5:
                prefix.append("")

            product_type, description = _split_middle(values[5:url_index])
            comments = ",".join(values[url_index + 1:])
            repaired = prefix + [
                product_type,
                description,
                values[url_index],
                comments,
            ]
            if len(repaired) == width:
                return repaired

    if len(values) < width:
        return values + [""] * (width - len(values))

    if width == 9 and len(values) > width:
        middle = values[5:-2]
        if len(middle) >= 2:
            product_type, description = _split_middle(middle)
            return values[:5] + [
                product_type,
                description,
                values[-2],
                values[-1],
            ]

    return values[:width - 1] + [",".join(values[width - 1:])]


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    header_start = _find_header_start(raw_csv)
    parse_text = raw_csv[header_start:] if header_start is not None else raw_csv
    records = _parse_records(parse_text)

    if not records:
        return {"columns": list(_EXPECTED_COLUMNS), "rows": []}

    if header_start is not None:
        header_index = 0
    else:
        scores = [_header_score(row) for row in records]
        best_score = max(scores) if scores else 0
        header_index = scores.index(best_score) if best_score >= 12 else 0

    header = [str(value) for value in records[header_index]]
    if header:
        header[0] = header[0].lstrip("\ufeff")

    expected_width = 9
    if len(header) < expected_width:
        header += _EXPECTED_COLUMNS[len(header):expected_width]
    elif len(header) > expected_width:
        header = header[:expected_width - 1] + [
            ",".join(header[expected_width - 1:])
        ]

    rows = [
        _repair_row(row, expected_width)
        for row in records[header_index + 1:]
    ]

    return {"columns": header, "rows": rows}
